using Microsoft.Dynamics365.LocalizationFramework;

/// <summary>
/// designed from AVA
/// </summary>
public class AVAERMemoryDestination implements ERIFileDestination
{
    private ERIFileDestination      originDestination;
    private AVAERReportToMemory     erReportToMemory;

}

Method.Source:
/// <summary>
/// Creates a stream for new file.
/// </summary>
/// <param name = "_fileName">Name of a new file.</param>
/// <returns>Stream for new file.</returns>
public System.IO.Stream newFileStream(System.String _fileName)
{
    return originDestination.newFileStream(_fileName);
}

/// <summary>
/// Saves file in destination.
/// </summary>
/// <param name = "_stream">A stream to save.</param>
/// <param name = "_fileName">A file name.</param>
/// <returns>Saved stream.</returns>
public System.IO.Stream saveFile(System.IO.Stream _stream, System.String _fileName)
{
    _stream.Seek(0, System.IO.SeekOrigin::Begin);

    System.IO.MemoryStream             ms;
    Binary                             binary;
    Map                                reportMap;

    ms     = _stream as System.IO.MemoryStream;



    if (ms != null)
    {
        if (ms.CanSeek)
        {
            ms.Seek(0, System.IO.SeekOrigin::Begin);
        }
        binary = Binary::constructFromMemoryStream(MS);
        if (erReportToMemory.RecId)
        {

           /* if (conLen(erReportToMemory.ReportMap) != 0)
            {
                reportMap = Map::create(erReportToMemory.ReportMap);
                erReportToMemory.ReportMap = conDel(erReportToMemory.ReportMap,1,1);
            }
            else 
            {
                reportMap = new Map(Types::String, Types::Class);
            }                       */

         /*   if(reportMap)
            {
                reportMap.insert(_fileName,_stream);
                container reportMapCont = reportMap.pack();

                erReportToMemory.ReportMap = conIns(erReportToMemory.ReportMap,1,reportMap.pack());
                //  erReportToMemory.ReportMap = reportMapCont;
            }     */
            if (conLen(erReportToMemory.ReportMap) != 0)
            {
                reportMap = Map::create(conPeek(erReportToMemory.ReportMap,1));
                erReportToMemory.ReportMap = conDel(erReportToMemory.ReportMap,1,1);
            }
            else
            {
                ReportMap = new Map(Types::String,Types::Container);
            }

            reportMap.insert(_fileName,binary.getContainer());
            erReportToMemory.ReportMap = conIns(erReportToMemory.ReportMap,1,ReportMap.pack());
         //   erReportToMemory.ReportMap = conIns(erReportToMemory.ReportMap,conLen(erReportToMemory.ReportMap)+1,ReportMap.pack());

            erReportToMemory.selectForUpdate(true);
            erReportToMemory.Report = binary.getContainer();
            ttsbegin;
            erReportToMemory.update();
            ttscommit;
        }
    }

    return _stream;
}

/// <summary>
/// Constructs destination for fixed asset roll forward report.
/// </summary>
/// <param name = "_originDestination">The original destination.</param>
/// <param name = "_erReportToMemory">The folder to store a report that's being created.</param>
/// <returns>The fixed asset roll forward destination.</returns>
public static AVAERMemoryDestination construct(ERIFileDestination _originDestination, AVAERReportToMemory  _erReportToMemory)
{
    return new AVAERMemoryDestination(_originDestination, _erReportToMemory);
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_originDestination">_originDestination</param>
/// <param name = "_erReportToMemory">_erReportToMemory</param>
protected void new(ERIFileDestination _originDestination, AVAERReportToMemory _erReportToMemory)
{
    originDestination = _originDestination;
    erReportToMemory = _erReportToMemory;
}
